    private static final class ScriptApi implements NativePipeEndpoint.Api {
        private byte[] pending;private int cursor;int readCalls,writes,guardChecks,disconnects,closes;long readBytes;
        synchronized void offer(byte[] packet){assertEquals(0,remaining(),"one pending packet maximum");pending=packet.clone();cursor=0;}
        synchronized int remaining(){return pending==null?0:pending.length-cursor;}
        public HANDLE CreateNamedPipeW(String n,int a,int b,int c,int d,int e,int f,Pointer g){throw new AssertionError("no real pipe create");}
        public boolean ConnectNamedPipe(HANDLE pipe,Pointer overlapped){return true;}
        public boolean GetNamedPipeClientProcessId(HANDLE pipe,IntByReference pid){pid.setValue(42);return true;}
        public synchronized boolean PeekNamedPipe(HANDLE pipe,Pointer buffer,int size,Pointer read,IntByReference available,Pointer left){available.setValue(remaining());return true;}
        public synchronized boolean ReadFile(HANDLE file,Pointer buffer,int length,IntByReference read,Pointer overlapped){readCalls++;int count=Math.min(length,remaining());assertTrue(count>0);buffer.write(0,pending,cursor,count);cursor+=count;readBytes+=count;read.setValue(count);if(cursor==pending.length){pending=null;cursor=0;}return true;}
        public boolean WriteFile(HANDLE file,Pointer buffer,int length,IntByReference written,Pointer overlapped){writes++;throw new AssertionError("no command writes");}
        public boolean DisconnectNamedPipe(HANDLE pipe){disconnects++;return true;}
        public boolean CloseHandle(HANDLE pipe){closes++;return true;}
    }
